cypress_script:
describe('Slider Control Tests', () => {
  it('should adjust the slider and display the correct value', () => {
    cy.visit('https://demoqa.com/slider');
    cy.get('#slider').invoke('val', 50).trigger('input');
    cy.get('#sliderValue').should('have.value', '50');
  });

  it('should not change the value if the slider is moved out of range', () => {
    cy.visit('https://demoqa.com/slider');
    cy.get('#slider').invoke('val', 100).trigger('input');
    cy.get('#sliderValue').should('have.value', '100');
    cy.get('#slider').invoke('val', -1).trigger('input');
    cy.get('#sliderValue').should('have.value', '100');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Slider Control Tests', () => {
  test('should adjust the slider and display the correct value', async ({ page }) => {
    await page.goto('https://demoqa.com/slider');
    await page.locator('#slider').fill('50');
    await page.locator('#slider').dispatchEvent('input');
    await expect(page.locator('#sliderValue')).toHaveValue('50');
  });

  test('should not change the value if the slider is moved out of range', async ({ page }) => {
    await page.goto('https://demoqa.com/slider');
    await page.locator('#slider').fill('100');
    await page.locator('#slider').dispatchEvent('input');
    await expect(page.locator('#sliderValue')).toHaveValue('100');
    await page.locator('#slider').fill('-1');
    await page.locator('#slider').dispatchEvent('input');
    await expect(page.locator('#sliderValue')).toHaveValue('100');
  });
});
